void radixSort(int arr[], int size) {
    if (size <= 1) return;

    // Find the maximum absolute value to determine number of digits
    int maxVal = 0;
    for (int i = 0; i < size; i++) {
        int absVal = abs(arr[i]);
        if (absVal > maxVal) maxVal = absVal;
    }

    // Temporary array for stable sorting
    int* output = new int[size];

    // Perform counting sort for each digit (base 10)
    for (int exp = 1; maxVal / exp > 0; exp *= 10) {
        // Count occurrences of digits (0-9)
        int count[10] = {0};

        // Store count of occurrences in count[]
        for (int i = 0; i < size; i++) {
            int digit = (abs(arr[i]) / exp) % 10;
            count[digit]++;
        }

        // Change count[i] so that count[i] contains actual
        // position of this digit in output[]
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        // Build the output array (from end to maintain stability)
        for (int i = size - 1; i >= 0; i--) {
            int digit = (abs(arr[i]) / exp) % 10;
            output[count[digit] - 1] = arr[i];
            count[digit]--;
        }

        // Copy the output array to arr[], so that arr[] now
        // contains sorted numbers according to current digit
        for (int i = 0; i < size; i++) {
            arr[i] = output[i];
        }
    }

    // Separate negative and positive numbers
    // Negative numbers are sorted in reverse order due to abs()
    int negCount = 0;
    for (int i = 0; i < size; i++) {
        if (arr[i] < 0) negCount++;
    }

    // If there are negative numbers, rearrange them
    if (negCount > 0) {
        // Negative numbers are at the beginning but in wrong order (largest magnitude first)
        // We need to reverse the negative portion and place it after positives
        int* temp = new int[size];

        // Copy positive numbers (in order)
        int posIdx = 0;
        for (int i = negCount; i < size; i++) {
            temp[posIdx++] = arr[i];
        }

        // Copy negative numbers in reverse order (to get correct ascending order)
        int negIdx = posIdx;
        for (int i = 0; i < negCount; i++) {
            temp[negIdx++] = arr[negCount - 1 - i];
        }

        // Copy back
        for (int i = 0; i < size; i++) {
            arr[i] = temp[i];
        }

        delete[] temp;
    }

    delete[] output;
}

